// WhatsApp links compose a message; the visitor reviews and sends it in WhatsApp.
function renderDimensions(p){const box=document.querySelector('#productDimensions');if(!p.dimensions){box.innerHTML='<h3>Medidas</h3><p>Por confirmar para esta referencia. Escríbenos por WhatsApp si necesitas verificar su tamaño antes de comprar.</p>';return}const m=p.dimensions;box.innerHTML=`<h3>Medidas de referencia</h3><dl><div><dt>Alto</dt><dd>≈ ${m.heightCm} cm</dd></div><div><dt>Ancho</dt><dd>≈ ${m.widthCm} cm</dd></div><div><dt>Fondo</dt><dd>≈ ${m.depthCm} cm</dd></div></dl><p>Según la ficha europea del fabricante para ${m.referenceModel}. Son medidas de referencia; confirma el tamaño físico por WhatsApp si necesitas un ajuste preciso.</p><a href="${m.source}" target="_blank" rel="noopener noreferrer">Consultar ficha de Sprayground <span aria-hidden="true">↗</span></a>`}
const WHATSAPP_PHONE='573188026232';
function whatsappLink(message){return 'https://wa.me/'+WHATSAPP_PHONE+'?text='+encodeURIComponent(message)}
function productWhatsApp(p){return whatsappLink('Hola, me interesa comprar el '+p.name+' de DISTRICT por '+money(p.price)+'. ¿Me confirmas disponibilidad, costo de envío en Medellín y medios de pago?')}
function selectionWhatsApp(){return whatsappLink('Hola, quiero consultar esta selección de DISTRICT:\n'+bag.map(id=>{const p=products.find(p=>p.id===id);return '• '+p.name+' · 1 unidad · '+money(p.price)}).join('\n')+'\nSubtotal de productos: '+money(bagTotal())+'\n¿Me confirmas disponibilidad, costo de envío en Medellín y medios de pago?')}
function updateSelectionWhatsApp(){const link=document.querySelector('#whatsappSelection');link.setAttribute('aria-disabled',String(!bag.length));if(bag.length){link.href=selectionWhatsApp();link.removeAttribute('tabindex')}else{link.removeAttribute('href');link.setAttribute('tabindex','-1')}}

const currencyFormatter=new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0});
function money(value){return currencyFormatter.format(value)+' COP'}
function bagTotal(){return bag.reduce((total,id)=>total+products.find(p=>p.id===id).price,0)}
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}let bag=read('district-bag',[]).filter(id=>products.some(p=>p.id===id)),favs=read('district-favs',[]),filter='all',onlyFav=false;function persist(){try{localStorage.setItem('district-bag',JSON.stringify(bag));localStorage.setItem('district-favs',JSON.stringify(favs))}catch{}document.querySelector('#count').textContent=bag.length}function render(){
 const list=products.filter(p=>(filter==='all'||p.id===filter)&&(!onlyFav||favs.includes(p.id)));
 document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===filter));
 document.querySelector('#resultCount').textContent=list.length+' '+(list.length===1?'diseño':'diseños')+(onlyFav?' en favoritos':'');
 document.querySelector('#products').innerHTML=list.length?list.map(p=>`<article><div class="card-photo"><button class="photo-button" onclick="showProduct('${p.id}')" aria-label="Explorar ${p.name}"><img src="assets/${p.photos[0]}.jpg" alt="Bolso ${p.name}" loading="lazy" width="960" height="1280"><img class="alternate-photo" src="assets/${p.photos[1]}.jpg" alt="" aria-hidden="true" loading="lazy" width="960" height="1280"><span class="card-photo-hint">VER TODOS LOS ÁNGULOS <span aria-hidden="true">↗</span></span></button><span class="product-tag">${p.tag}</span><button class="heart" onclick="favorite('${p.id}')" aria-label="${favs.includes(p.id)?'Quitar':'Guardar'} ${p.name} ${favs.includes(p.id)?'de':'en'} favoritos" aria-pressed="${favs.includes(p.id)}">${favs.includes(p.id)?'♥':'♡'}</button></div><div class="card-bottom"><div><h3>${p.name}</h3><p>${p.sub}</p><p class="catalog-price">${money(p.price)}</p><p class="photo-count">Sprayground original · ${p.photos.length} fotografías</p></div><button class="card-open" onclick="showProduct('${p.id}')" aria-label="Ver detalles de ${p.name}"><span>Ver bolso</span><b aria-hidden="true">↗</b></button></div><a class="product-whatsapp" href="${productWhatsApp(p)}" target="_blank" rel="noopener noreferrer" aria-label="Comprar ${p.name} por WhatsApp">Comprar por WhatsApp <span aria-hidden="true">↗</span></a></article>`).join(''):`<div class="catalog-empty"><span aria-hidden="true">♡</span><h3>${onlyFav?'Sin favoritos en esta selección':'Sin diseños en esta selección'}</h3><p>${onlyFav?'Guarda un diseño con el corazón o vuelve a explorar la colección completa.':'Prueba con otro filtro para explorar la colección.'}</p><button class="primary" onclick="resetCatalog()">Ver todos los diseños <span aria-hidden="true">↗</span></button></div>`;
}
function resetCatalog(){filter='all';onlyFav=false;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));const f=document.querySelector('#favFilter');f.classList.remove('active');f.setAttribute('aria-pressed',false);render()}
function favorite(id){favs=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];persist();render()}function showProduct(id){const p=products.find(p=>p.id===id);document.querySelector('#modalTitle').textContent=p.name;renderDimensions(p);document.querySelector('#whatsappProduct').href=productWhatsApp(p);document.querySelector('#whatsappProduct').setAttribute('aria-label','Comprar '+p.name+' por WhatsApp');document.querySelector('#modalText').textContent=p.text;document.querySelector('#modalPrice').textContent=money(p.price);document.querySelector('#designInfo').textContent=p.info;setPhoto(p.photos[0],p.name);document.querySelector('#thumbnails').innerHTML=p.photos.map((photo,i)=>`<button onclick="setPhoto('${photo}','${p.name}')" aria-label="${p.name}: ${p.photoLabels[i]}"><img src="assets/${photo}.jpg" alt=""></button>`).join('');document.querySelector('#addBag').onclick=()=>{if(!bag.includes(id)){bag.push(id);persist();toast('Añadido a tu selección')}else toast('Este bolso ya está en tu selección')};document.querySelector('#productDialog').showModal()}function setPhoto(photo,name){const im=document.querySelector('#modalImage');im.src=`assets/${photo}.jpg`;im.alt=`${name} — ${photo==='back'?'vista posterior':photo==='detail'?'detalle de etiquetas':'vista del diseño'}`}function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}function renderBag(){document.querySelector('#cartItems').innerHTML=bag.length?bag.map(id=>{const p=products.find(x=>x.id===id);return `<div class="cart-row"><img src="assets/${p.photos[0]}.jpg" alt="${p.name}"><div><b>${p.name}</b><p class="muted">1 unidad · ${money(p.price)}</p></div><button onclick="removeBag('${id}')">Quitar</button></div>`}).join(''):'<p>Tu bolsa está esperando un poco de actitud. Explora la colección y guarda tu diseño favorito.</p>';document.querySelector('#cartTotal').textContent=money(bagTotal());document.querySelector('#copySelection').disabled=!bag.length;updateSelectionWhatsApp()}function removeBag(id){bag=bag.filter(x=>x!==id);persist();renderBag()}document.querySelector('#cartOpen').onclick=()=>{renderBag();document.querySelector('#cartDialog').showModal()};document.querySelector('#copySelection').onclick=async()=>{const s='Mi selección DISTRICT — Sprayground originales:\n'+bag.map(id=>{const p=products.find(p=>p.id===id);return p.name+' · 1 unidad · '+money(p.price)}).join('\n')+'\nSubtotal: '+money(bagTotal())+'\nEntrega en Medellín: costo y disponibilidad por confirmar. Esta selección no constituye un pedido.';try{await navigator.clipboard.writeText(s);toast('Selección copiada')}catch{toast('No se pudo copiar. Selección: '+bag.map(id=>products.find(p=>p.id===id).name).join(', '))}};document.querySelector('#zoomButton').onclick=()=>{document.querySelector('#zoomed').src=document.querySelector('#modalImage').src;document.querySelector('#zoomDialog').showModal()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#favFilter').onclick=function(){onlyFav=!onlyFav;this.classList.toggle('active',onlyFav);this.setAttribute('aria-pressed',onlyFav);render()};function skin(s){document.body.dataset.skin=s;document.documentElement.style.colorScheme=s==='studio'?'light':'dark';document.querySelectorAll('[data-skin]').forEach(b=>{if(b.tagName==='BUTTON'){b.classList.toggle('active',b.dataset.skin===s);b.setAttribute('aria-pressed',b.dataset.skin===s)}});try{localStorage.setItem('district-skin',JSON.stringify(s))}catch{}}document.querySelectorAll('.skins button').forEach(b=>b.onclick=()=>skin(b.dataset.skin));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));skin(read('district-skin','street'));persist();render();

// Motion and editorial interactions.
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const modelButtons=[...document.querySelectorAll('[data-model]')];
let heroModel='shark',heroTimer;
function selectHero(id){if(id===heroModel)return;heroModel=id;const p=products.find(x=>x.id===id),frame=document.querySelector('#heroExplore');modelButtons.forEach(b=>{const selected=b.dataset.model===id;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected)});frame.classList.add('changing');clearTimeout(heroTimer);heroTimer=setTimeout(()=>{const photo=document.querySelector('#heroPhoto');photo.src=`assets/${p.photos[0]}.jpg`;photo.alt=`Bolso ${p.name}`;frame.onclick=()=>showProduct(id);frame.setAttribute('aria-label',`Explorar bolso ${p.name}`);document.querySelector('#heroName').textContent=p.name;document.querySelector('#heroPrice').textContent=money(p.price);document.querySelector('#heroSubtitle').textContent=({shark:'Un poco de instinto. Mucha actitud.',hello:'Una presentación que no necesita palabras.',graffiti:'Un trazo propio. Sin pasar desapercibido.'})[id] || 'Tu carácter, en cada detalle.';const loaded=()=>frame.classList.remove('changing');if(photo.complete)loaded();else{photo.onload=loaded;photo.onerror=loaded}},reducedMotion?0:220)}
modelButtons.forEach(b=>b.onclick=()=>selectHero(b.dataset.model));
let galleryProduct=products[0],galleryIndex=0;
const baseShowProduct=showProduct,baseSetPhoto=setPhoto;
setPhoto=function(photo,name){baseSetPhoto(photo,name);galleryIndex=galleryProduct.photos.indexOf(photo);if(galleryIndex<0)galleryIndex=0;const img=document.querySelector('#modalImage');const caption=galleryProduct.photoLabels[galleryIndex];img.alt=`${galleryProduct.name} — ${caption}`;document.querySelector('#photoCaption').textContent=caption;if(!reducedMotion){img.classList.remove('photo-swap');void img.offsetWidth;img.classList.add('photo-swap')}document.querySelector('#photoCounter').textContent=`${String(galleryIndex+1).padStart(2,'0')} / ${String(galleryProduct.photos.length).padStart(2,'0')}`;document.querySelectorAll('#thumbnails button').forEach((b,i)=>{b.classList.toggle('selected',i===galleryIndex);b.setAttribute('aria-pressed',i===galleryIndex)});document.querySelector('#photoPrev').disabled=galleryProduct.photos.length<2;document.querySelector('#photoNext').disabled=galleryProduct.photos.length<2};
showProduct=function(id){galleryProduct=products.find(p=>p.id===id);galleryIndex=0;baseShowProduct(id);setPhoto(galleryProduct.photos[0],galleryProduct.name)};
function stepPhoto(delta){galleryIndex=(galleryIndex+delta+galleryProduct.photos.length)%galleryProduct.photos.length;setPhoto(galleryProduct.photos[galleryIndex],galleryProduct.name)}
document.querySelector('#photoPrev').onclick=()=>stepPhoto(-1);document.querySelector('#photoNext').onclick=()=>stepPhoto(1);
document.querySelector('#productDialog').addEventListener('keydown',e=>{if(document.querySelector('#zoomDialog').open)return;if(e.key==='ArrowRight'){stepPhoto(1);e.preventDefault()}if(e.key==='ArrowLeft'){stepPhoto(-1);e.preventDefault()}});
let swipeStart=0;const swipeArea=document.querySelector('#zoomButton');swipeArea.addEventListener('touchstart',e=>{swipeStart=e.changedTouches[0].clientX},{passive:true});swipeArea.addEventListener('touchend',e=>{const distance=e.changedTouches[0].clientX-swipeStart;if(Math.abs(distance)>45){stepPhoto(distance<0?1:-1);swipeArea.dataset.swiped='true';setTimeout(()=>delete swipeArea.dataset.swiped,400)}},{passive:true});const baseZoom=swipeArea.onclick;swipeArea.onclick=e=>{if(!swipeArea.dataset.swiped)baseZoom(e)};
let revealObserver;
if(!reducedMotion&&'IntersectionObserver' in window){document.documentElement.classList.add('js-motion');revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}})},{threshold:.09});document.querySelectorAll('.section-top,.details .detail-copy,.skin-content,.skin-art,.closing,.products article').forEach(el=>{el.classList.add('reveal');revealObserver.observe(el)})}
const baseRender=render;render=function(){baseRender();document.querySelectorAll('.products article').forEach((el,i)=>{if(!reducedMotion)el.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:550,delay:i*90,easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'})})};
let ticking=false;function updateReading(){const range=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.transform=`scaleX(${range>0?Math.min(1,scrollY/range):0})`;ticking=false}window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateReading);ticking=true}},{passive:true});updateReading();

// A scroll-driven typographic sequence inspired by the supplied motion reference.
let motionPaused=reducedMotion,motionFrame=false;
const motionButton=document.querySelector('#motionToggle');
const story=document.querySelector('#motionStory');
const storyWords=[...document.querySelectorAll('.story-word')];
function paintStory(){motionFrame=false;if(motionPaused||reducedMotion)return;const bounds=story.getBoundingClientRect();const distance=Math.max(1,story.offsetHeight-innerHeight);const progress=Math.max(0,Math.min(1,-bounds.top/distance));storyWords.forEach((word,i)=>{const center=i/2;const delta=progress-center;const visible=Math.max(0,1-Math.abs(delta)*3.3);word.style.opacity=visible;word.style.transform=`translateX(${delta*-110}px) scale(${1+Math.abs(delta)*.15}) skewX(${delta*-5}deg)`;word.style.filter=`blur(${Math.min(12,Math.abs(delta)*15)}px)`});const beam=document.querySelector('.story-beam');beam.style.transform=`translateY(${(progress-.5)*95}px) rotate(${-12+progress*24}deg)`}
function queueStory(){if(!motionFrame&&!motionPaused){motionFrame=true;requestAnimationFrame(paintStory)}}
function setMotionPaused(paused){motionPaused=paused;document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',paused);motionButton.textContent=paused?'ACTIVAR MOVIMIENTO ▷':'PAUSAR MOVIMIENTO Ⅱ';if(!paused)paintStory()}
motionButton.onclick=()=>setMotionPaused(!motionPaused);setMotionPaused(reducedMotion);
window.addEventListener('scroll',queueStory,{passive:true});window.addEventListener('resize',queueStory,{passive:true});
modelButtons.forEach(button=>button.addEventListener('click',()=>{document.querySelector('.stage-watermark').textContent=({shark:'SHARK',hello:'HELLO',graffiti:'GRAFF',yellow:'SHARK',dark:'SHARK'})[button.dataset.model]}));
